package com.dragosfotache.gymtracka.data.sync.model

/**
 * Typed offline mutation requests for this slice. Kind wire strings match the
 * OpenAPI Mutation variants exactly, including clone/copy child-ID plans and
 * history additions. IDs are never generated by mappings.
 */

/** Explicit OpenAPI Mutation kind wire strings as a typed discriminator. */
enum class MutationKind(val wireValue: String) {
    WORKOUT_START("workout.start"),
    WORKOUT_UPSERT("workout.upsert"),
    WORKOUT_FINISH("workout.finish"),
    WORKOUT_PERFORM_AGAIN("workout.performAgain"),
    ROUTINE_START_WORKOUT("routine.startWorkout"),
    WORKOUT_SAVE_AS_ROUTINE("workout.saveAsRoutine"),
    WORKOUT_ADD_EXERCISES("workout.addExercises"),
    WORKOUT_REPLACE_EXERCISE("workout.replaceExercise"),
    WORKOUT_DELETE_EXERCISE("workout.deleteExercise"),
    WORKOUT_DELETE_SET("workout.deleteSet"),
    ROUTINE_UPSERT("routine.upsert"),
    ROUTINE_SAVE("routine.save"),
    ROUTINE_DELETE_EXERCISE("routine.deleteExercise"),
    ROUTINE_DELETE_SET("routine.deleteSet"),
    CUSTOM_EXERCISE_UPSERT("customExercise.upsert"),
    AGGREGATE_DELETE("aggregate.delete"),
    AGGREGATE_IMPORT("aggregate.import"),
    ;

    companion object {
        fun fromWire(wireValue: String): MutationKind =
            entries.singleOrNull { it.wireValue == wireValue }
                ?: throw SyncModelException("Unknown mutation kind: $wireValue")
    }
}

/**
 * Workout import snapshot. Like upload input but explicitly allows a valid
 * finished snapshot (timestamp, completed survivors) alongside active ones.
 * No revision, display names, or derived volume.
 */
data class WorkoutImportModel(
    val id: String,
    val name: String,
    val status: String,
    val startedAtMillis: Long,
    val finishedAtMillis: Long?,
    val exercises: List<WorkoutExerciseInputModel>,
)

/** Typed import record union, discriminated by the envelope aggregate type. */
sealed class ImportRecord {
    abstract val aggregateId: String

    data class Workout(val input: WorkoutImportModel) : ImportRecord() {
        override val aggregateId: String get() = input.id
    }

    data class Routine(val input: RoutineInputModel) : ImportRecord() {
        override val aggregateId: String get() = input.id
    }

    data class CustomExercise(val input: CustomExerciseInputModel) : ImportRecord() {
        override val aggregateId: String get() = input.id
    }
}

/** One planned stable set identity binding source and target set IDs. */
data class ChildSetBinding(
    val sourceSetId: String,
    val id: String,
)

/** One planned stable exercise identity with its ordered set bindings. */
data class ChildExerciseBinding(
    val sourceExerciseId: String,
    val id: String,
    val sets: List<ChildSetBinding>,
)

/** One planned workout-exercise addition with stable set IDs for server history. */
data class ExerciseAddition(
    val id: String,
    val exerciseId: String,
    val setIds: List<String>,
)

/** Typed mutation payload union. Never a generic map or raw JSON object. */
sealed class MutationPayload {
    data class WorkoutStart(val id: String, val name: String, val startedAtMillis: Long) : MutationPayload()

    data class WorkoutUpsert(val input: WorkoutInputModel) : MutationPayload()

    data class WorkoutFinish(val finishedAtMillis: Long) : MutationPayload()

    data class WorkoutPerformAgain(
        val sourceWorkoutId: String,
        val id: String,
        val startedAtMillis: Long,
        val childIds: List<ChildExerciseBinding>,
    ) : MutationPayload()

    data class RoutineStartWorkout(
        val sourceRoutineId: String,
        val id: String,
        val startedAtMillis: Long,
        val childIds: List<ChildExerciseBinding>,
    ) : MutationPayload()

    data class WorkoutSaveAsRoutine(
        val sourceWorkoutId: String,
        val id: String,
        val name: String,
        val childIds: List<ChildExerciseBinding>,
    ) : MutationPayload()

    data class WorkoutAddExercises(val additions: List<ExerciseAddition>) : MutationPayload()

    data class WorkoutReplaceExercise(val workoutExerciseId: String, val exerciseId: String) :
        MutationPayload()

    data class WorkoutDeleteExercise(val workoutExerciseId: String) : MutationPayload()

    data class WorkoutDeleteSet(val workoutSetId: String) : MutationPayload()

    data class RoutineUpsert(val input: RoutineInputModel) : MutationPayload()

    data class RoutineSave(val name: String) : MutationPayload()

    data class RoutineDeleteExercise(val routineExerciseId: String) : MutationPayload()

    data class RoutineDeleteSet(val routineSetId: String) : MutationPayload()

    data class CustomExerciseUpsert(val input: CustomExerciseInputModel) : MutationPayload()

    data object AggregateDelete : MutationPayload()

    data class AggregateImport(val record: ImportRecord) : MutationPayload()
}

/** Typed offline mutation envelope. Mirrors OpenAPI MutationEnvelope exactly. */
data class MutationEnvelopeModel(
    val mutationId: String,
    val kind: MutationKind,
    val aggregateType: AggregateType,
    val aggregateId: String,
    val localGeneration: Long,
    val knownServerRevision: Long?,
    val payload: MutationPayload,
)
